const loadExternalListings = async () => { const feeds = parseFeedConfig(process.env.EXTERNAL_MARKETPLACE_FEEDS_JSON); let stored = []; try { await ensureAuthSchema(); stored = await query('SELECT external_id, source, source_label, title, category, city, province, price, image_url, url, item_type, description, summary_source, is_demo, provenance, observed_at FROM external_listings ORDER BY observed_at DESC LIMIT 100'); } catch (error) { console.error('[external-listing-read]', error.message); } if (!feeds.length) return { data: stored, meta: { live_sync: false, configured_feeds: 0, imported_urls: stored.length, notice: stored.length ? 'Menampilkan kartu dari URL yang telah diimpor admin.' : 'Belum ada feed produk resmi yang dikonfigurasi.' } }; const all = [...stored]; const statuses = []; for (const feed of feeds) { const cached = externalFeedCache.get(`products:${feed.id}`); if (cached && cached.expires > Date.now()) { all.push(...cached.data); statuses.push({ id: feed.id, status: 'cache', count: cached.data.length }); continue; } try { const payload = await fetchJsonFeed(feed); const rows = feedItems(payload, feed).filter(item => feed.region_filter === true ? regionMatches(item, feed, feed.include_unknown === true) : true).map(item => normalizeExternalItem(feed, item)).filter(Boolean).slice(0, 100); await Promise.all(rows.map(persistExternalListing)); externalFeedCache.set(`products:${feed.id}`, { data: rows, expires: Date.now() + Number(feed.cache_seconds || 300) * 1000 }); all.push(...rows); statuses.push({ id: feed.id, status: 'ok', count: rows.length, region_filter: feed.region_filter === true }); } catch (error) { statuses.push({ id: feed.id, status: 'error', message: error.name === 'AbortError' ? 'timeout' : 'unavailable' }); } } const unique = [...new Map(all.map(row => [`${row.source}:${row.external_id}`, row])).values()]; return { data: unique.slice(0, 100), meta: { live_sync: true, configured_feeds: feeds.length, imported_urls: stored.length, feeds: statuses } }; };
const normalizeExternalJob = (feed, item) => { const row = item || {}; const title = row.title || row.name || row.position || row.job_title; const url = row.url || row.link || row.apply_url; if (!title || !url || !/^https:\/\//.test(String(url))) return null; return { external_id: String(row.id || row.external_id || crypto.createHash('sha256').update(`${feed.id}:${title}:${url}`).digest('hex').slice(0, 20)), source: feed.id, source_label: feed.label || feed.id, title: String(title).slice(0, 180), company: String(row.company || row.company_name || row.employer || 'Perusahaan lokal').slice(0, 140), city: String(row.city || row.location || row.district || '').slice(0, 80), province: String(row.province || 'Sulawesi Tenggara').slice(0, 80), category: String(row.category || row.job_category || 'Umum').slice(0, 80), employment_type: String(row.employment_type || row.type || 'Tidak disebutkan').slice(0, 60), salary_text: String(row.salary || row.salary_text || '').slice(0, 120), description: String(row.description || row.summary || '').slice(0, 1000), image_url: /^https:\/\//.test(String(row.image_url || row.image || '')) ? String(row.image_url || row.image).slice(0, 1000) : null, posted_at: row.posted_at || row.published_at || null, expires_at: row.expires_at || row.deadline || null, observed_at: new Date().toISOString(), url: String(url).slice(0, 1000), provenance: feed.provenance || 'authorized_partner_feed' }; };
