const loadExternalJobs = async () => { const feeds = parseFeedConfig(process.env.EXTERNAL_JOB_FEEDS_JSON); let stored = []; try { await ensureAuthSchema(); stored = await query('SELECT external_id, source, source_label, title, company, city, province, category, employment_type, salary_text, description, url, image_url, posted_at, expires_at, observed_at, provenance FROM external_jobs ORDER BY observed_at DESC LIMIT 100'); } catch (error) { console.error('[external-job-read]', error.message); } if (!feeds.length) return { data: stored, meta: { live_sync: false, configured_feeds: 0, imported_urls: stored.length, notice: stored.length ? 'Menampilkan lowongan dari URL yang telah diimpor admin.' : 'Belum ada feed atau URL lowongan resmi yang dikonfigurasi.' } }; const all = [...stored]; const statuses = []; for (const feed of feeds) { const cached = externalFeedCache.get(`jobs:${feed.id}`); if (cached && cached.expires > Date.now()) { all.push(...cached.data); statuses.push({ id: feed.id, status: 'cache', count: cached.data.length }); continue; } try { const payload = await fetchJsonFeed(feed); const rows = feedItems(payload, feed).filter(item => regionMatches(item, feed, feed.include_unknown === true)).map(item => normalizeExternalJob(feed, item)).filter(Boolean).slice(0, 100); await Promise.all(rows.map(persistExternalJob)); externalFeedCache.set(`jobs:${feed.id}`, { data: rows, expires: Date.now() + Number(feed.cache_seconds || 300) * 1000 }); all.push(...rows); statuses.push({ id: feed.id, status: 'ok', count: rows.length, region_filter: true }); } catch (error) { statuses.push({ id: feed.id, status: 'error', message: error.name === 'AbortError' ? 'timeout' : 'unavailable' }); } } const unique = [...new Map(all.map(row => [`${row.source}:${row.external_id}`, row])).values()]; return { data: unique.slice(0, 100), meta: { live_sync: true, configured_feeds: feeds.length, imported_urls: stored.length, feeds: statuses } }; };
