const otpDestinationHash = (channel, destination) => crypto.createHash('sha256').update(`${channel}:${destination}:${process.env.OTP_DESTINATION_PEPPER || ''}`).digest('hex');
const parseJsonValue = value => { try { return typeof value === 'string' ? JSON.parse(value) : value; } catch { return null; } };
const parseJsonObject = value => { const parsed = parseJsonValue(value); return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {}; };
const parseJsonArray = value => { const parsed = parseJsonValue(value); return Array.isArray(parsed) ? parsed : []; };
const boundedText = (value, max) => safeText(value, max);
const onboardingData = (value, fields) => { const source = parseJsonObject(value); return Object.fromEntries(fields.map(field => { const item = source[field]; if (Array.isArray(item)) return [field, item.slice(0, 8).map(entry => boundedText(entry, 80))]; if (typeof item === 'number') return [field, Number.isFinite(item) ? item : '']; return [field, typeof item === 'boolean' ? item : boundedText(item, field === 'description' ? 2000 : 240)]; })); };
