app.post('/api/seller/onboarding/finalize', requireAuth, async (req, res, next) => { try { await ensureAuthSchema(); if (!['seller', 'admin', 'super_admin'].includes(normalizeRole(req.user.role))) return fail(res, 403, 'Akun belum memiliki hak seller'); const storeData = onboardingData(req.body?.store_data, onboardingFields.store); const productData = onboardingData(req.body?.product_data, onboardingFields.product); const title = boundedText(productData.title, 120); const description = boundedText(productData.description, 2000); const price = Number(productData.price); const categoryId = Number(productData.category_id); const condition = productData.condition || 'new'; const district = districts.includes(productData.district || storeData.district) ? (productData.district || storeData.district) : 'Kendari'; if (title.length < 5 || description.length < 10 || !Number.isInteger(price) || price < 0 || !positiveInt(categoryId) || !['new', 'second'].includes(condition)) return fail(res, 422, 'Detail produk belum lengkap atau belum valid'); const listingResult = await run('INSERT INTO listings (seller_id, category_id, title, description, price, condition, district, city, image_url) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)', [currentUser(req), categoryId, title, description, price, condition, district, 'Kendari', null]); await run('UPDATE users SET store_name = COALESCE(NULLIF(?, \'\'), store_name), store_description = COALESCE(NULLIF(?, \'\'), store_description), district = ? WHERE id = ?', [storeData.store_name || null, storeData.store_description || null, district, currentUser(req)]); await run("UPDATE seller_onboarding_progress SET current_step = 4, status = 'completed', product_data = ?::jsonb, store_data = ?::jsonb, completed_steps = '[1,2,3,4]'::jsonb, completed_at = now(), updated_at = now() WHERE user_id = ?", [JSON.stringify(productData), JSON.stringify(storeData), currentUser(req)]); const [listing] = await query('SELECT * FROM listings WHERE id = ?', [listingResult.id]); res.status(201); ok(res, { listing, message: 'Onboarding seller selesai. Produk pertama siap dipublikasikan.' }); } catch (error) { next(error); } });
app.post('/api/auth/request-otp', otpRateLimit, async (req, res, next) => {
  try {
    await ensureAuthSchema();
    const channel = req.body?.channel === 'email' ? 'email' : 'whatsapp';
    const phone = channel === 'whatsapp' ? String(req.body?.phone || '').trim() : null;
    const email = channel === 'email' ? normalizeEmail(req.body?.email) : null;
    if (channel === 'whatsapp' && !/^08\d{8,13}$/.test(phone || '')) return fail(res, 422, 'Nomor WhatsApp Indonesia belum valid');
    if (channel === 'email' && !email) return fail(res, 422, 'Alamat email belum valid');
    const destination = channel === 'email' ? email : phone;
    const destinationHash = otpDestinationHash(channel, destination);
    const code = String(crypto.randomInt(100000, 1000000));
    const codeHash = crypto.createHash('sha256').update(code).digest('hex');
    await run('DELETE FROM auth_otp_challenges WHERE (channel = ? AND destination_hash = ?) OR expires_at < now()', [channel, destinationHash]);
    await run("INSERT INTO auth_otp_challenges (channel, destination_hash, code_hash, expires_at) VALUES (?, ?, ?, now() + interval '5 minutes')", [channel, destinationHash, codeHash]);
    let delivered = false;
    try { delivered = await sendOtp(channel, destination, code); } catch (error) { console.error(`[otp-${channel}]`, error.message); if (process.env.OTP_DEV_MODE !== 'true') { await run('DELETE FROM auth_otp_challenges WHERE channel = ? AND destination_hash = ? AND consumed_at IS NULL', [channel, destinationHash]); return failCode(res, 503, 'OTP_PROVIDER_UNAVAILABLE', `OTP ${channel} sedang tidak tersedia. Coba lagi nanti.`); } }
    if (!delivered && process.env.OTP_DEV_MODE !== 'true') { await run('DELETE FROM auth_otp_challenges WHERE channel = ? AND destination_hash = ? AND consumed_at IS NULL', [channel, destinationHash]); return failCode(res, 503, 'OTP_NOT_CONFIGURED', `OTP ${channel} belum dikonfigurasi.`); }
    const response = { channel, destination: channel === 'email' ? maskEmail(email) : phone, expires_in: 300, delivered, message: delivered ? `Kode OTP telah dikirim melalui ${channel === 'email' ? 'email' : 'WhatsApp'}.` : 'Mode demo lokal aktif; gunakan kode yang ditampilkan.' };
    if (process.env.OTP_DEV_MODE === 'true') response.dev_code = code;
    ok(res, response);
  } catch (error) { next(error); }
});

