app.post('/api/auth/verify-otp', otpRateLimit, async (req, res, next) => {
  try {
    await ensureAuthSchema();
    const channel = req.body?.channel === 'email' ? 'email' : 'whatsapp';
    const phone = channel === 'whatsapp' ? String(req.body?.phone || '').trim() : null;
    const email = channel === 'email' ? normalizeEmail(req.body?.email) : null;
    const code = String(req.body?.code || '').trim(); const name = String(req.body?.name || 'Pengguna SultraKita'); const role = req.body?.role || 'buyer'; const district = req.body?.district || 'Kendari';
    if ((channel === 'whatsapp' && !/^08\d{8,13}$/.test(phone || '')) || (channel === 'email' && !email) || !/^\d{6}$/.test(code)) return fail(res, 422, 'Tujuan atau kode OTP belum valid');
    const destination = channel === 'email' ? email : phone;
    const destinationHash = otpDestinationHash(channel, destination);
    const [challenge] = await query("SELECT id, code_hash, attempts FROM auth_otp_challenges WHERE channel = ? AND destination_hash = ? AND consumed_at IS NULL AND expires_at > now() AND attempts < 5 ORDER BY id DESC LIMIT 1", [channel, destinationHash]);
    if (!challenge) return fail(res, 401, 'OTP sudah kedaluwarsa atau tidak ditemukan');
    const hash = crypto.createHash('sha256').update(code).digest('hex'); const matches = hash.length === challenge.code_hash.length && crypto.timingSafeEqual(Buffer.from(hash), Buffer.from(challenge.code_hash)); if (!matches) { await run('UPDATE auth_otp_challenges SET attempts = attempts + 1 WHERE id = ?', [challenge.id]); return fail(res, 401, 'Kode OTP salah'); }
    let [user] = await query(channel === 'email' ? 'SELECT * FROM users WHERE lower(email) = lower(?) LIMIT 1' : 'SELECT * FROM users WHERE phone = ? LIMIT 1', [destination]);
    if (!user) { const created = await run('INSERT INTO users (name, phone, email, role, district, phone_verified, email_verified) VALUES (?, ?, ?, ?, ?, ?, ?)', [name.trim().slice(0, 80), phone, email, ['buyer','seller'].includes(role) ? role : 'buyer', districts.includes(district) ? district : 'Kendari', channel === 'whatsapp', channel === 'email']); [user] = await query('SELECT * FROM users WHERE id = ?', [created.id]); } else { await run(`UPDATE users SET ${channel === 'email' ? 'email_verified' : 'phone_verified'} = true WHERE id = ?`, [user.id]); user = { ...user, ...(channel === 'email' ? { email_verified: true } : { phone_verified: true }) }; }
    await run('UPDATE auth_otp_challenges SET consumed_at = now() WHERE id = ?', [challenge.id]); const token = await issueSession(user.id);
    ok(res, { token, user: { id: user.id, name: user.name, phone: user.phone, email: user.email, role: user.role, district: user.district, phone_verified: Boolean(user.phone_verified) || channel === 'whatsapp', email_verified: Boolean(user.email_verified) || channel === 'email', verification_status: user.verification_status || 'unverified' } });
  } catch (error) { next(error); }
});

app.post('/api/users', async (req, res, next) => {
  try {
    const { name, phone, role = 'seller', district = 'Kendari' } = req.body || {};
    if (!name || name.trim().length < 2 || !phone || !/^08\d{8,13}$/.test(phone)) return fail(res, 422, 'name minimal 2 karakter dan phone harus nomor Indonesia yang valid');
    if (!['buyer', 'seller'].includes(role) || !districts.includes(district)) return fail(res, 422, 'role atau district tidak valid');
    const result = await run('INSERT INTO users (name, phone, role, district) VALUES (?, ?, ?, ?)', [name.trim(), phone, role, district]);
    const [user] = await query('SELECT id, name, phone, role, district, is_verified, created_at FROM users WHERE id = ?', [result.id]);
    res.status(201); ok(res, user);
  } catch (error) {
    if (String(error.message).includes('UNIQUE constraint failed')) return fail(res, 409, 'Nomor telepon sudah terdaftar');
    next(error);
  }
});

