app.post('/api/seller-verifications', async (req, res, next) => { try { const { user_id, document_type, document_reference = null } = req.body || {}; if (!positiveInt(user_id) || !['ktp','nib','other'].includes(document_type)) return fail(res, 422, 'user_id atau document_type belum valid'); if (!req.user) return fail(res, 401, 'Autentikasi diperlukan'); if (Number(req.user.id) !== Number(user_id) && !['admin', 'super_admin'].includes(normalizeRole(req.user.role))) return fail(res, 403, 'Identitas user tidak sesuai session'); const result = await run('INSERT INTO seller_verifications (user_id, document_type, document_reference) VALUES (?, ?, ?)', [Number(user_id), document_type, document_reference]); await run("UPDATE users SET verification_status = 'pending' WHERE id = ?", [Number(user_id)]); res.status(201); ok(res, { id: result.id, status: 'pending', message: 'Pengajuan verifikasi seller diterima untuk ditinjau admin.' }); } catch (error) { next(error); } });

app.post('/api/uploads/presign', requireAuth, async (req, res, next) => { try { const listingId = Number(req.body?.listingId); const files = Array.isArray(req.body?.files) ? req.body.files : []; if (!positiveInt(listingId) || !files.length || files.length > 5) return fail(res, 422, 'listingId dan maksimal 5 file wajib diisi'); const [listing] = await query('SELECT id, seller_id FROM listings WHERE id = ?', [listingId]); if (!listing) return fail(res, 404, 'Listing tidak ditemukan'); if (!['admin', 'super_admin'].includes(normalizeRole(req.user.role)) && Number(listing.seller_id) !== Number(req.user.id)) return fail(res, 403, 'Akses tidak diizinkan'); if (!process.env.R2_PRESIGN_URL) return failCode(res, 503, 'STORAGE_UNAVAILABLE', 'Upload foto sedang belum tersedia. Coba lagi setelah storage dikonfigurasi.'); const normalized = files.map(file => ({ name: safeText(file.name, 160), type: String(file.type || '').toLowerCase(), size: Number(file.size) })).filter(file => /^image\/(jpeg|png|webp)$/.test(file.type) && Number.isSafeInteger(file.size) && file.size > 0 && file.size <= 5 * 1024 * 1024); if (normalized.length !== files.length) return fail(res, 422, 'Setiap file harus JPG, PNG, atau WEBP maksimal 5 MB'); const response = await fetch(process.env.R2_PRESIGN_URL, { method: 'POST', headers: { authorization: `Bearer ${process.env.R2_UPLOAD_TOKEN || ''}`, 'content-type': 'application/json' }, body: JSON.stringify({ listingId, files: normalized }) }); if (!response.ok) return failCode(res, 503, 'STORAGE_UNAVAILABLE', 'Storage tidak dapat membuat URL upload sementara.'); const payload = await response.json(); if (!Array.isArray(payload.uploads) || payload.uploads.length !== normalized.length) return failCode(res, 502, 'STORAGE_INVALID_RESPONSE', 'Storage memberikan respons upload yang tidak valid.'); return ok(res, payload.uploads); } catch (error) { console.error('[upload-presign]', error.message); return next(error); } });

app.post('/api/uploads/commit', requireAuth, async (req, res, next) => { try { const listingId = Number(req.body?.listingId); const uploads = Array.isArray(req.body?.uploads) ? req.body.uploads : []; if (!positiveInt(listingId) || !uploads.length || uploads.length > 5) return fail(res, 422, 'listingId dan metadata upload belum valid'); const [listing] = await query('SELECT id, seller_id FROM listings WHERE id = ?', [listingId]); if (!listing) return fail(res, 404, 'Listing tidak ditemukan'); if (!['admin', 'super_admin'].includes(normalizeRole(req.user.role)) && Number(listing.seller_id) !== Number(req.user.id)) return fail(res, 403, 'Akses tidak diizinkan'); const existing = await query('SELECT COUNT(*) AS total FROM listing_images WHERE listing_id = ?', [listingId]); if (Number(existing[0]?.total || 0) + uploads.length > 5) return fail(res, 422, 'Maksimal lima foto per listing'); const base = String(process.env.R2_PUBLIC_BASE_URL || '').replace(/\/$/, ''); const committed = []; for (const [index, uploadItem] of uploads.entries()) { const fileUrl = String(uploadItem.publicUrl || ''); if (!base || !fileUrl.startsWith(`${base}/`)) return fail(res, 422, 'URL foto tidak berasal dari storage resmi'); const result = await run('INSERT INTO listing_images (listing_id, file_url, sort_order) VALUES (?, ?, ?)', [listingId, fileUrl.slice(0, 1000), Number(existing[0].total) + index]); committed.push({ id: result.id, file_url: fileUrl }); } return ok(res, committed); } catch (error) { next(error); } });

const hasValidImageSignature = async file => { const bytes = file.buffer; const jpeg = bytes.length >= 3 && bytes[0] === 0xff && bytes[1] === 0xd8 && bytes[2] === 0xff; const png = bytes.length >= 8 && Buffer.from(bytes.subarray(0, 8)).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])); const webp = bytes.length >= 12 && bytes.subarray(0, 4).toString() === 'RIFF' && bytes.subarray(8, 12).toString() === 'WEBP'; return (file.mimetype === 'image/jpeg' && jpeg) || (file.mimetype === 'image/png' && png) || (file.mimetype === 'image/webp' && webp); };
app.post('/api/listings/:id/images', requireAuth, upload.array('images', 5), async (req, res, next) => { try { if (!positiveInt(req.params.id)) return fail(res, 400, 'ID listing tidak valid'); if (!req.files?.length) return fail(res, 422, 'Minimal satu foto JPG, PNG, atau WEBP diperlukan'); for (const file of req.files) if (!(await hasValidImageSignature(file))) return fail(res, 422, 'Isi file gambar tidak sesuai dengan MIME yang diizinkan'); const listing = await query('SELECT id, seller_id FROM listings WHERE id = ?', [Number(req.params.id)]); if (!listing.length) return fail(res, 404, 'Listing tidak ditemukan'); if (!['admin', 'super_admin'].includes(normalizeRole(req.user.role)) && Number(listing[0].seller_id) !== Number(req.user.id)) return fail(res, 403, 'Akses tidak diizinkan'); const existing = await query('SELECT COUNT(*) AS total FROM listing_images WHERE listing_id = ?', [Number(req.params.id)]); const images = []; for (const [index, file] of req.files.entries()) { const fileUrl = await uploadObject(file); await run('INSERT INTO listing_images (listing_id, file_url, sort_order) VALUES (?, ?, ?)', [Number(req.params.id), fileUrl, Number(existing[0].total) + index]); images.push(fileUrl); } ok(res, images); } catch (error) { next(error); } });

