app.put('/api/admin/rbac/assignments/:userId', requirePermission('manage_roles'), adminOnly, async (req, res, next) => { try { const userId = Number(req.params.userId); const role = String(req.body?.role || '').trim().toLowerCase(); const allowedRoles = ['user', 'seller', 'moderator', 'support', 'analyst', 'admin', 'super_admin']; if (!positiveInt(userId) || !allowedRoles.includes(role)) return fail(res, 422, 'userId atau role tidak valid'); if (Number(req.user.id) === userId && role !== 'super_admin') return fail(res, 409, 'Super Admin tidak dapat menurunkan role dirinya sendiri'); const result = await withTransaction(async ({ query: txQuery, run: txRun }) => { const [target] = await txQuery('SELECT id, role FROM users WHERE id = ?', [userId]); if (!target) return null; if (['user', 'seller'].includes(role)) { await txRun('DELETE FROM admin_role_assignments WHERE user_id = ?', [userId]); await txRun('UPDATE users SET role = ? WHERE id = ?', [role === 'user' ? 'buyer' : 'seller', userId]); } else { await txRun('INSERT INTO admin_role_assignments (user_id, role, assigned_by) VALUES (?, ?, ?) ON CONFLICT (user_id) DO UPDATE SET role = EXCLUDED.role, assigned_by = EXCLUDED.assigned_by, updated_at = now()', [userId, role, req.user.id]); } await auditAdminAction({ run: txRun }, req, 'role_assigned', 'user', userId, { previous_legacy_role: target.role, assigned_role: role }); return { user_id: userId, role }; }); if (!result) return fail(res, 404, 'Pengguna tidak ditemukan'); ok(res, result); } catch (error) { next(error); } });
