const universalLinkRow = async (url, categoryOverride = '') => { const base = await fetchJobUrlMetadata(url); const category = inferLinkCategory(`${base.title} ${base.description} ${base.url}`, categoryOverride); return { external_id: base.external_id, source: `link-url:${base.source_label}`, source_label: base.source_label, title: base.title, category, city: base.city, province: base.province, price: null, image_url: base.image_url, url: base.url, item_type: category === 'lowongan' ? 'job' : 'product', description: base.description, summary_source: 'metadata_fallback', is_demo: false, provenance: base.provenance, observed_at: base.observed_at }; };
