app.post('/api/conversations', async (req, res, next) => { try { const { listing_id, buyer_id, seller_id } = req.body || {}; if (!positiveInt(buyer_id) || !positiveInt(seller_id)) return fail(res, 422, 'buyer_id dan seller_id wajib valid'); if (!req.user) return fail(res, 401, 'Autentikasi diperlukan'); if (Number(req.user.id) !== Number(buyer_id) && !['admin', 'super_admin'].includes(normalizeRole(req.user.role))) return fail(res, 403, 'Identitas buyer tidak sesuai session'); if (positiveInt(listing_id)) { const [listing] = await query('SELECT seller_id FROM listings WHERE id = ?', [Number(listing_id)]); if (!listing) return fail(res, 404, 'Listing tidak ditemukan'); if (Number(listing.seller_id) !== Number(seller_id) && !['admin', 'super_admin'].includes(normalizeRole(req.user.role))) return fail(res, 403, 'Seller tidak sesuai dengan listing'); } const existing = await query('SELECT * FROM conversations WHERE listing_id IS NOT DISTINCT FROM ? AND buyer_id = ? AND seller_id = ?', [listing_id || null, Number(buyer_id), Number(seller_id)]); if (existing.length) return ok(res, existing[0]); const created = await run('INSERT INTO conversations (listing_id, buyer_id, seller_id) VALUES (?, ?, ?)', [listing_id || null, Number(buyer_id), Number(seller_id)]); const [conversation] = await query('SELECT * FROM conversations WHERE id = ?', [created.id]); res.status(201); ok(res, conversation); } catch (error) { next(error); } });
app.use('/api/conversations/:id/messages', async (req, res, next) => { if (!positiveInt(req.params.id)) return fail(res, 400, 'ID percakapan tidak valid'); if (req.method === 'POST' && (!positiveInt(req.body?.sender_id) || !req.body?.body || String(req.body.body).trim().length < 1 || String(req.body.body).trim().length > 2000)) return next(); if (!req.user) return fail(res, 401, 'Autentikasi diperlukan'); const [member] = await query('SELECT id FROM conversations WHERE id = ? AND (buyer_id = ? OR seller_id = ?)', [Number(req.params.id), Number(req.user.id), Number(req.user.id)]); if (!member && !['admin', 'super_admin'].includes(normalizeRole(req.user.role))) return fail(res, 403, 'Akses tidak diizinkan'); next(); });
app.use('/api/conversations/:id/stream', async (req, res, next) => { if (!positiveInt(req.params.id)) return fail(res, 400, 'ID percakapan tidak valid'); if (!req.user) return fail(res, 401, 'Autentikasi diperlukan'); const [member] = await query('SELECT id FROM conversations WHERE id = ? AND (buyer_id = ? OR seller_id = ?)', [Number(req.params.id), Number(req.user.id), Number(req.user.id)]); if (!member && !['admin', 'super_admin'].includes(normalizeRole(req.user.role))) return fail(res, 403, 'Akses tidak diizinkan'); next(); });
app.get('/api/conversations/:id/messages', async (req, res, next) => { try { if (!positiveInt(req.params.id)) return fail(res, 400, 'ID percakapan tidak valid'); if (!req.user) return fail(res, 401, 'Autentikasi diperlukan'); const [member] = await query('SELECT id FROM conversations WHERE id = ? AND (buyer_id = ? OR seller_id = ?)', [Number(req.params.id), Number(req.user.id), Number(req.user.id)]); if (!member && !['admin', 'super_admin'].includes(normalizeRole(req.user.role))) return fail(res, 403, 'Akses tidak diizinkan'); ok(res, await query('SELECT m.*, u.name AS sender_name FROM messages m JOIN users u ON u.id = m.sender_id WHERE m.conversation_id = ? ORDER BY m.created_at ASC', [Number(req.params.id)])); } catch (error) { next(error); } });
app.post('/api/conversations/:id/messages', async (req, res, next) => { try { const { sender_id, body } = req.body || {}; if (!positiveInt(sender_id) || !body || body.trim().length < 1 || body.trim().length > 2000) return fail(res, 422, 'sender_id dan pesan belum valid'); if (!req.user) return fail(res, 401, 'Autentikasi diperlukan'); if (Number(req.user.id) !== Number(sender_id) && !['admin', 'super_admin'].includes(normalizeRole(req.user.role))) return fail(res, 403, 'Identitas pengirim tidak sesuai session'); const conversations = await query('SELECT c.*, l.title AS listing_title, seller.name AS seller_name, seller.phone AS seller_phone FROM conversations c LEFT JOIN listings l ON l.id = c.listing_id LEFT JOIN users seller ON seller.id = c.seller_id WHERE c.id = ?', [Number(req.params.id)]); if (!conversations.length) return fail(res, 404, 'Percakapan tidak ditemukan'); const conversation = conversations[0]; if (conversation.status !== 'open') return fail(res, 409, 'Percakapan sudah ditutup'); const created = await run('INSERT INTO messages (conversation_id, sender_id, body) VALUES (?, ?, ?)', [Number(req.params.id), Number(req.user.id), body.trim()]); await run('UPDATE conversations SET updated_at = CURRENT_TIMESTAMP WHERE id = ?', [Number(req.params.id)]); const [message] = await query('SELECT m.*, u.name AS sender_name FROM messages m JOIN users u ON u.id = m.sender_id WHERE m.id = ?', [created.id]); if (Number(sender_id) === Number(conversation.buyer_id)) void notifySellerWhatsApp({ phone:conversation.seller_phone, sellerName:conversation.seller_name, listingTitle:conversation.listing_title, senderName:message.sender_name, message:message.body, channel:'pesan pembeli' }); res.status(201); ok(res, message); } catch (error) { next(error); } });
app.get('/api/conversations/:id/stream', async (req, res) => { if (!positiveInt(req.params.id)) return res.status(400).end(); res.setHeader('Content-Type', 'text/event-stream'); res.setHeader('Cache-Control', 'no-cache'); res.setHeader('Connection', 'keep-alive'); res.flushHeaders?.(); res.write(': connected\n\n'); let lastId = Number(req.query.after || 0); const timer = setInterval(async () => { try { const rows = await query('SELECT m.*, u.name AS sender_name FROM messages m JOIN users u ON u.id = m.sender_id WHERE m.conversation_id = ? AND m.id > ? ORDER BY m.id ASC', [Number(req.params.id), lastId]); for (const message of rows) { lastId = message.id; res.write(`data: ${JSON.stringify(message)}\\n\\n`); } } catch { clearInterval(timer); res.end(); } }, 2000); req.on('close', () => clearInterval(timer)); });

app.post('/api/dev/whatsapp-webhook', async (req, res, next) => { try { const expected = process.env.SIMULATION_TOKEN || 'local-only'; if (process.env.NODE_ENV === 'production' || req.get('x-simulation-token') !== expected) return fail(res, 404, 'Not found'); const payload = req.body || {}; if (payload.event !== 'messages.upserted' || !payload.message?.body || !payload.seller?.phone) return fail(res, 422, 'Payload simulasi webhook belum valid'); console.info('[whatsapp-simulation]', { message_id:payload.message.id, seller_phone_last4:String(payload.seller.phone).slice(-4), listing_id:payload.listing?.id }); ok(res, { simulated:true, would_notify:payload.seller.phone, provider_called:false, message_id:payload.message.id }); } catch (error) { next(error); } });

app.post('/api/analytics/track', analyticsRateLimit, async (req, res, next) => { try { const { event_name, path: pagePath = '/', listing_id = null, category_slug = null, district = null, referrer = null } = req.body || {}; const allowed = ['page_view','listing_view','search','listing_contact']; if (!allowed.includes(event_name)) return fail(res, 422, 'event_name analitik tidak valid'); await run('INSERT INTO analytics_events (event_name, path, listing_id, category_slug, district, referrer, user_agent, country_code) VALUES (?, ?, ?, ?, ?, ?, ?, ?)', [event_name, String(pagePath).slice(0, 300), positiveInt(listing_id) ? Number(listing_id) : null, category_slug ? String(category_slug).slice(0, 80) : null, district ? String(district).slice(0, 80) : null, referrer ? String(referrer).slice(0, 300) : null, req.get('user-agent')?.slice(0, 300) || null, req.get('cf-ipcountry') || null]); res.status(202); ok(res, { tracked: true }); } catch (error) { next(error); } });
app.get('/api/analytics/summary', requirePermission('view_analytics'), adminOnly, async (req, res, next) => { try { const days = Math.min(90, Math.max(1, Number(req.query.days) || 7)); const [totals] = await query("SELECT COUNT(*) AS events, COUNT(*) FILTER (WHERE event_name = 'page_view') AS page_views, COUNT(*) FILTER (WHERE event_name = 'listing_view') AS listing_views, COUNT(*) FILTER (WHERE event_name = 'search') AS searches, COUNT(*) FILTER (WHERE event_name = 'listing_contact') AS contacts FROM analytics_events WHERE created_at >= now() - (? * interval '1 day')", [`-${days} days`]); const topListings = await query("SELECT l.id, l.title, l.views, COUNT(a.id) AS tracked_views FROM listings l LEFT JOIN analytics_events a ON a.listing_id = l.id AND a.event_name = 'listing_view' AND a.created_at >= now() - (? * interval '1 day') GROUP BY l.id ORDER BY tracked_views DESC, l.views DESC LIMIT 10", [`-${days} days`]); const daily = await query("SELECT created_at::date AS date, COUNT(*)::int AS events, COUNT(*) FILTER (WHERE event_name = 'page_view')::int AS page_views, COUNT(*) FILTER (WHERE event_name = 'listing_view')::int AS listing_views FROM analytics_events WHERE created_at >= now() - (? * interval '1 day') GROUP BY created_at::date ORDER BY date ASC", [`-${days} days`]); ok(res, { days, totals, top_listings: topListings, daily }); } catch (error) { next(error); } });

app.get('/api/public-config', (_req, res) => ok(res, { supabase_url: process.env.SUPABASE_URL || null, supabase_anon_key: process.env.SUPABASE_ANON_KEY || null }));

app.get('/api/sellers/:id', async (req, res, next) => {
  try {
    const sellerId = Number(req.params.id);
    if (!positiveInt(sellerId)) return fail(res, 400, 'ID seller tidak valid');
    const [seller] = await query('SELECT id, name, district, bio, rating_average, rating_count, is_verified, phone_verified, verification_status, created_at FROM users WHERE id = ?', [sellerId]);
    if (!seller) return fail(res, 404, 'Seller tidak ditemukan');
    const listings = await query("SELECT l.id, l.title, l.price, l.district, l.city, l.image_url, l.created_at, c.name AS category_name, c.slug AS category_slug FROM listings l LEFT JOIN categories c ON c.id = l.category_id WHERE l.seller_id = ? AND l.status = 'active' ORDER BY l.created_at DESC LIMIT 6", [sellerId]);
    const [sold] = await query("SELECT COUNT(*)::int AS sold_count FROM listings WHERE seller_id = ? AND status = 'sold'", [sellerId]);
    ok(res, { seller: { id: seller.id, name: seller.name, district: seller.district, bio: seller.bio, rating_average: Number(seller.rating_average || 0), rating_count: Number(seller.rating_count || 0), verified: Boolean(seller.is_verified || seller.phone_verified || seller.verification_status === 'approved'), joined_at: seller.created_at, sold_count: Number(sold?.sold_count || 0) }, listings });
  } catch (error) { next(error); }
});
app.get('/api/stats', async (_req, res, next) => {
  try {
    const [summary] = await query(`SELECT COUNT(*)::int AS total_listings, COUNT(*) FILTER (WHERE status = 'active')::int AS active_listings, COUNT(DISTINCT district) FILTER (WHERE status = 'active')::int AS covered_districts, COUNT(*) FILTER (WHERE status = 'active' AND CASE WHEN created_at::text ~ '^\\d{4}-' THEN created_at::timestamptz ELSE NULL END >= now() - interval '7 days')::int AS weekly_new_listings FROM listings`);
    const popular = await query(`SELECT c.name AS category, COUNT(l.id) AS total FROM categories c LEFT JOIN listings l ON l.category_id = c.id AND l.status = 'active' GROUP BY c.id ORDER BY total DESC, c.name LIMIT 5`);
    ok(res, { summary, popular_categories: popular });
  } catch (error) { next(error); }
});

app.get('/api/listings', async (req, res, next) => {
  try {
    const page = Math.max(1, Number.parseInt(req.query.page || '1', 10));
    const limit = Math.min(50, Math.max(1, Number.parseInt(req.query.limit || '12', 10)));
    const offset = (page - 1) * limit;
    const params = [];
    const filters = ['l.status = ?']; params.push('active');
    if (req.query.q) { filters.push('(LOWER(l.title) LIKE LOWER(?) OR LOWER(l.description) LIKE LOWER(?) OR LOWER(l.city) LIKE LOWER(?))'); const q = `%${req.query.q}%`; params.push(q, q, q); }
    if (req.query.category) { filters.push('c.slug = ?'); params.push(req.query.category); }
    if (req.query.district) { filters.push('l.district = ?'); params.push(req.query.district); }
    if (req.query.condition) { filters.push('l.condition = ?'); params.push(req.query.condition); }
    if (positiveInt(req.query.min_price)) { filters.push('l.price >= ?'); params.push(Number(req.query.min_price)); }
    if (positiveInt(req.query.max_price)) { filters.push('l.price <= ?'); params.push(Number(req.query.max_price)); }
    const allowedSort = { newest: 'l.created_at DESC', cheapest: 'l.price ASC', expensive: 'l.price DESC', popular: 'l.views DESC' };
    const order = allowedSort[req.query.sort] || allowedSort.newest;
    const where = filters.join(' AND ');
    // Cast to text before normalizing so legacy bigint 0/1 and modern boolean values both work.
    const sellerVerifiedSql = "CASE WHEN COALESCE(u.verification_status, 'unverified') = 'approved' OR LOWER(COALESCE(u.is_verified::text, 'false')) IN ('1', 'true', 't', 'yes', 'y') THEN 1 ELSE 0 END";
    const items = await query(`SELECT l.*, c.name AS category_name, c.slug AS category_slug, u.name AS seller_name, u.phone AS seller_phone, ${sellerVerifiedSql} AS seller_verified, COALESCE(u.rating_average, l.seller_rating, 0) AS seller_rating, COALESCE(u.rating_count, 0) AS seller_review_count, (SELECT COUNT(*) FROM comments cm WHERE cm.listing_id = l.id AND cm.status = 'visible') AS comment_count FROM listings l JOIN categories c ON c.id = l.category_id LEFT JOIN users u ON u.id = l.seller_id WHERE ${where} ORDER BY ${order} LIMIT ? OFFSET ?`, [...params, limit, offset]);
    const [{ total }] = await query(`SELECT COUNT(*) AS total FROM listings l JOIN categories c ON c.id = l.category_id WHERE ${where}`, params);
    const publicItems = items.map(item => { const safe = { ...item }; delete safe.seller_phone; return safe; });
    ok(res, publicItems, { page, limit, total: Number(total), total_pages: Math.ceil(Number(total) / limit), location: 'Kendari, Sulawesi Tenggara' });
  } catch (error) { console.error('[listings-fallback]', error.message); ok(res, [], { page: 1, limit: 0, total: 0, total_pages: 0, source: 'degraded', notice: 'Listing sementara belum tersedia. Silakan coba lagi.' }); }
});

app.get('/api/sellers/:id', async (req, res, next) => { try { if (!positiveInt(req.params.id)) return fail(res, 400, 'ID seller tidak valid'); const [seller] = await query("SELECT id, name, avatar_url, bio, role, district, rating_average, rating_count, is_verified, verification_status, created_at FROM users WHERE id = ?", [Number(req.params.id)]); if (!seller) return fail(res, 404, 'Seller tidak ditemukan'); const listings = await query("SELECT l.id, l.title, l.description, l.price, l.condition, l.status, l.district, l.city, l.image_url, l.views, l.created_at, c.name AS category_name, c.slug AS category_slug FROM listings l JOIN categories c ON c.id = l.category_id WHERE l.seller_id = ? AND l.status = 'active' ORDER BY l.created_at DESC LIMIT 50", [Number(req.params.id)]); ok(res, { seller: { ...seller, rating_average: Number(seller.rating_average || 0), rating_count: Number(seller.rating_count || 0), verified: Boolean(Number(seller.is_verified) || seller.verification_status === 'approved') }, listings }); } catch (error) { next(error); } });

app.get('/api/listings/:id', async (req, res, next) => {
  try {
    if (!positiveInt(req.params.id)) return fail(res, 400, 'ID listing tidak valid');
    const sellerVerifiedSql = "CASE WHEN COALESCE(u.verification_status, 'unverified') = 'approved' OR LOWER(COALESCE(u.is_verified::text, 'false')) IN ('1', 'true', 't', 'yes', 'y') THEN 1 ELSE 0 END";
    const rows = await query(`SELECT l.*, c.name AS category_name, c.slug AS category_slug, u.name AS seller_name, u.phone AS seller_phone, ${sellerVerifiedSql} AS seller_verified, COALESCE(u.rating_average, l.seller_rating, 0) AS seller_rating, COALESCE(u.rating_count, 0) AS seller_review_count, (SELECT COUNT(*) FROM comments cm WHERE cm.listing_id = l.id AND cm.status = 'visible') AS comment_count, u.district AS seller_district FROM listings l JOIN categories c ON c.id = l.category_id LEFT JOIN users u ON u.id = l.seller_id WHERE l.id = ? AND l.status = 'active'`, [Number(req.params.id)]);
    if (!rows.length) return fail(res, 404, 'Listing tidak ditemukan');
    await run('UPDATE listings SET views = views + 1, views_count = COALESCE(views_count, 0) + 1 WHERE id = ?', [Number(req.params.id)]); const forwardedIp = String(req.get('x-forwarded-for') || '').split(',')[0].trim(); const clientIp = /^[0-9a-f:.]+$/i.test(forwardedIp) ? forwardedIp : null; await run('INSERT INTO listing_views (listing_id, user_id, ip_address, user_agent) VALUES (?, ?, ?, ?)', [Number(req.params.id), req.user?.id || null, clientIp, req.get('user-agent')?.slice(0, 300) || null]);
    const publicListing = { ...rows[0], seller_rating: Number(rows[0].seller_rating || 0), seller_review_count: Number(rows[0].seller_review_count || 0), comment_count: Number(rows[0].comment_count || 0) }; delete publicListing.seller_phone;
    ok(res, publicListing);
  } catch (error) { next(error); }
});

app.post('/api/listings', async (req, res, next) => {
  try {
    const { title, description, price, category_id, condition = 'new', district = 'Kendari' } = req.body || {};
    const errors = [];
    if (!title || title.trim().length < 5 || title.trim().length > 120) errors.push('title wajib 5-120 karakter');
    if (!description || description.trim().length < 10) errors.push('description wajib minimal 10 karakter');
    if (!positiveInt(category_id)) errors.push('category_id wajib berupa ID positif');
    if (!Number.isInteger(Number(price)) || Number(price) < 0) errors.push('price wajib berupa angka >= 0');
    if (!['new', 'second'].includes(condition)) errors.push('condition harus new atau second');
    if (!districts.includes(district)) errors.push('district belum didukung');
    if (errors.length) return fail(res, 422, 'Data listing belum valid', errors);
    if (!req.user) return fail(res, 401, 'Autentikasi diperlukan');
    if (!['seller', 'admin', 'super_admin'].includes(normalizeRole(req.user.role))) return fail(res, 403, 'Akun belum memiliki hak seller');
    const result = await run(`INSERT INTO listings (seller_id, category_id, title, description, price, condition, district, city, image_url) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`, [req.user.id, Number(category_id), title.trim(), description.trim(), Number(price), condition, district, 'Kendari', null]);
    const [listing] = await query('SELECT * FROM listings WHERE id = ?', [result.id]);
    res.status(201); ok(res, listing);
  } catch (error) { next(error); }
});

app.put('/api/listings/:id', async (req, res, next) => {
  try {
    if (!positiveInt(req.params.id)) return fail(res, 400, 'ID listing tidak valid');
    if (!req.user) return fail(res, 401, 'Autentikasi diperlukan');
    const { title, description, price, category_id, condition = 'new', district = 'Kendari' } = req.body || {};
    if (!title || title.trim().length < 5 || title.trim().length > 120 || !description || description.trim().length < 10 || !positiveInt(category_id) || !Number.isInteger(Number(price)) || Number(price) < 0 || !['new', 'second'].includes(condition) || !districts.includes(district)) return fail(res, 422, 'Data listing belum valid');
    const owned = await query('SELECT id FROM listings WHERE id = ? AND seller_id = ?', [Number(req.params.id), Number(req.user.id)]);
    if (!owned.length && !['admin', 'super_admin'].includes(normalizeRole(req.user.role))) return fail(res, 403, 'Akses tidak diizinkan');
    await run('UPDATE listings SET title = ?, description = ?, price = ?, category_id = ?, condition = ?, district = ?, city = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?', [title.trim(), description.trim(), Number(price), Number(category_id), condition, district, 'Kendari', Number(req.params.id)]);
    const [listing] = await query('SELECT * FROM listings WHERE id = ?', [Number(req.params.id)]);
    ok(res, listing);
  } catch (error) { next(error); }
});

app.patch('/api/listings/:id/status', requireAuth, async (req, res, next) => { try { const status = ['active', 'sold', 'archived'].includes(req.body?.status) ? req.body.status : null; if (!status) return fail(res, 422, 'Status listing tidak valid'); const [owned] = await query('SELECT id FROM listings WHERE id = ? AND (seller_id = ? OR ? = \'admin\')', [Number(req.params.id), currentUser(req), req.user.role]); if (!owned) return fail(res, 403, 'Akses tidak diizinkan'); await run('UPDATE listings SET status = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?', [status, Number(req.params.id)]); ok(res, { id: Number(req.params.id), status }); } catch (error) { next(error); } });
app.post('/api/listings/:id/promote', requireAuth, async (req, res, next) => { try { const [owned] = await query('SELECT id FROM listings WHERE id = ? AND (seller_id = ? OR ? = \'admin\')', [Number(req.params.id), currentUser(req), req.user.role]); if (!owned) return fail(res, 403, 'Akses tidak diizinkan'); await run("UPDATE listings SET is_promoted = TRUE, promoted_until = (CURRENT_TIMESTAMP + interval '7 days'), updated_at = CURRENT_TIMESTAMP WHERE id = ? AND status = 'active'", [Number(req.params.id)]); ok(res, { id: Number(req.params.id), is_promoted: true, duration_days: 7, message: 'Promosi beta aktif selama 7 hari.' }); } catch (error) { next(error); } });

